const std = @import("std"); const builtin = @import("builtin"); const winz = std.os.windows; const pausctrl = @import("ru-paus-ctrl.zig");
pub const PausCode = pausctrl.PausCode; pub const pausResp = pausctrl.codeResp;
const CF = .{ .clas = 9, .kill = 0x2000, .capz = 256 * 1024, .slee = 5, .exit = 1 };
extern "kernel32" fn CreateJobObjectW(lpJobAttributes: ?*anyopaque, lpName: ?[*:0]const u16) callconv(.winapi) ?winz.HANDLE;
extern "kernel32" fn AssignProcessToJobObject(hJob: winz.HANDLE, hProcess: winz.HANDLE) callconv(.winapi) c_int;
extern "kernel32" fn TerminateJobObject(hJob: winz.HANDLE, uExitCode: c_uint) callconv(.winapi) c_int;
extern "kernel32" fn SetInformationJobObject(hJob: winz.HANDLE, class: c_int, info: *anyopaque, len: u32) callconv(.winapi) c_int;
extern "kernel32" fn TerminateProcess(hProcess: winz.HANDLE, uExitCode: c_uint) callconv(.winapi) c_int;
const JobzBasiLimi = extern struct { per_process_user_time: i64 = 0, per_job_user_time: i64 = 0, limit_flags: u32 = 0, min_ws: usize = 0, max_ws: usize = 0, active_process_limit: u32 = 0, affinity: usize = 0, priority_class: u32 = 0, scheduling_class: u32 = 0 };
const JobzExteLimi = extern struct { basic: JobzBasiLimi = .{}, io_counters: [6]u64 = @splat(0), process_memory_limit: usize = 0, job_memory_limit: usize = 0, peak_process_memory: usize = 0, peak_job_memory: usize = 0 };
fn killOnzzClosSetz(hand: winz.HANDLE, onzz: bool) bool { if (builtin.os.tag != .windows) return false; var info: JobzExteLimi = .{}; info.basic.limit_flags = if (onzz) @as(u32, CF.kill) else 0; return SetInformationJobObject(hand, CF.clas, &info, @sizeOf(JobzExteLimi)) != 0; }
fn jobzRele(hand: winz.HANDLE) void { if (builtin.os.tag != .windows) return; _ = killOnzzClosSetz(hand, false); _ = winz.CloseHandle(hand); }
pub fn jobzHandRele(hand: winz.HANDLE) void { jobzRele(hand); }
pub const Ring = struct {
pub const CAPZ = CF.capz;
gpaz: std.mem.Allocator, mute: std.Io.Mutex = .init, bufz: std.ArrayList(u8) = .empty, base: u64 = 0, done: bool = false, refs: std.atomic.Value(u32) = .init(1), cmdz: []const u8, cwdz: []const u8, tabz: []const u8, star_msec: i64,
pub fn crea(gpaz: std.mem.Allocator, cmdz: []const u8, cwdz: []const u8, tabz: []const u8, star_msec: i64) !*Ring { const ring = try gpaz.create(Ring); errdefer gpaz.destroy(ring); ring.* = .{ .gpaz = gpaz, .cmdz = try gpaz.dupe(u8, cmdz), .cwdz = try gpaz.dupe(u8, cwdz), .tabz = try gpaz.dupe(u8, tabz), .star_msec = star_msec }; return ring; }
pub fn appe(self: *Ring, iozz: std.Io, line: []const u8) void { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); if (self.bufz.items.len + line.len > CAPZ) { const half = self.bufz.items.len / 2; const cutz = if (std.mem.indexOfScalarPos(u8, self.bufz.items, half, '\n')) |nlin| nlin + 1 else self.bufz.items.len; std.mem.copyForwards(u8, self.bufz.items[0 .. self.bufz.items.len - cutz], self.bufz.items[cutz..]); self.bufz.shrinkRetainingCapacity(self.bufz.items.len - cutz); self.base += cutz; } if (line.len > CAPZ) return; self.bufz.appendSlice(self.gpaz, line) catch {}; }
pub fn fini(self: *Ring, iozz: std.Io) void { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); self.done = true; }
pub fn fromRead(self: *Ring, iozz: std.Io, from: u64, outz: []u8) struct { byte: usize, next: u64, done: bool, lost: bool } { self.mute.lock(iozz) catch return .{ .byte = 0, .next = from, .done = true, .lost = false }; defer self.mute.unlock(iozz); const lost = from < self.base; const star = if (lost) self.base else from; const endz = self.base + self.bufz.items.len; if (star >= endz) return .{ .byte = 0, .next = star, .done = self.done, .lost = lost }; const offz: usize = @intCast(star - self.base); const byte = @min(outz.len, self.bufz.items.len - offz); @memcpy(outz[0..byte], self.bufz.items[offz..][0..byte]); return .{ .byte = byte, .next = star + byte, .done = self.done and star + byte == endz, .lost = lost }; }
pub fn doneChec(self: *Ring, iozz: std.Io) bool { self.mute.lock(iozz) catch return true; defer self.mute.unlock(iozz); return self.done; }
pub fn size(self: *Ring, iozz: std.Io) u64 { self.mute.lock(iozz) catch return self.base; defer self.mute.unlock(iozz); return self.base + self.bufz.items.len; }
pub fn reta(self: *Ring) void { _ = self.refs.fetchAdd(1, .acq_rel); }
pub fn rele(self: *Ring) void { if (self.refs.fetchSub(1, .acq_rel) != 1) return; const gpaz = self.gpaz; self.bufz.deinit(gpaz); gpaz.free(self.cmdz); gpaz.free(self.cwdz); gpaz.free(self.tabz); gpaz.destroy(self); }
};
pub const Entr = struct { chil: *std.process.Child, ring: ?*Ring = null, jobz: ?winz.HANDLE = null, done: bool = false, keep: bool = false, stdi_user: u32 = 0, stdi_clos_done: bool = false, stdi_clos_requ: bool = false, paus: bool = false, paus_star: i64 = 0, paus_tota: i64 = 0 };
pub const Regi = struct {
mapz: std.StringHashMapUnmanaged(Entr) = .empty, mute: std.Io.Mutex = .init, gpaz: std.mem.Allocator = undefined,
pub fn dein(self: *Regi, allo: std.mem.Allocator) void { var iter = self.mapz.iterator(); while (iter.next()) |entr| { if (entr.value_ptr.jobz) |hand| jobzRele(hand); if (entr.value_ptr.ring) |ring| ring.rele(); allo.free(entr.key_ptr.*); } self.mapz.deinit(allo); }
pub fn addz(self: *Regi, iozz: std.Io, jobz_iden: []const u8, entr: Entr) !void { try self.mute.lock(iozz); defer self.mute.unlock(iozz); const gopz = try self.mapz.getOrPut(self.gpaz, jobz_iden); if (!gopz.found_existing) gopz.key_ptr.* = try self.gpaz.dupe(u8, jobz_iden); gopz.value_ptr.* = entr; }
pub fn doneMark(self: *Regi, iozz: std.Io, jobz_iden: []const u8) void { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); if (self.mapz.getPtr(jobz_iden)) |entr| { if (entr.jobz) |hand| { jobzRele(hand); entr.jobz = null; } entr.done = true; } }
pub fn remo(self: *Regi, iozz: std.Io, jobz_iden: []const u8) void { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); if (self.mapz.fetchRemove(jobz_iden)) |kvpr| { if (kvpr.value.jobz) |hand| jobzRele(hand); if (kvpr.value.ring) |ring| ring.rele(); self.gpaz.free(kvpr.key); } }
pub fn ringJobz(self: *Regi, iozz: std.Io, jobz_iden: []const u8) ?*Ring { self.mute.lock(iozz) catch return null; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return null; const ring = entr.ring orelse return null; ring.reta(); return ring; }
pub fn jobsWrit(self: *Regi, iozz: std.Io, wrtr: *std.Io.Writer) !void { try self.mute.lock(iozz); defer self.mute.unlock(iozz); try wrtr.writeAll("{\"jobs\":["); var firs = true; var iter = self.mapz.iterator(); while (iter.next()) |kvpr| { const ring = kvpr.value_ptr.ring orelse continue; if (!firs) try wrtr.writeAll(","); firs = false; try wrtr.writeAll("{\"id\":"); try std.json.Stringify.encodeJsonString(kvpr.key_ptr.*, .{}, wrtr); try wrtr.writeAll(",\"cmd\":"); try std.json.Stringify.encodeJsonString(ring.cmdz, .{}, wrtr); try wrtr.writeAll(",\"cwd\":"); try std.json.Stringify.encodeJsonString(ring.cwdz, .{}, wrtr); try wrtr.writeAll(",\"tab\":"); try std.json.Stringify.encodeJsonString(ring.tabz, .{}, wrtr); try wrtr.print(",\"started\":{d},\"keep\":{},\"done\":{},\"bytes\":{d},\"paused\":{}}}", .{ ring.star_msec, kvpr.value_ptr.keep, kvpr.value_ptr.done, ring.size(iozz), kvpr.value_ptr.paus }); } try wrtr.writeAll("]}"); }
pub fn liveCoun(self: *Regi, iozz: std.Io) ?usize { self.mute.lock(iozz) catch return null; defer self.mute.unlock(iozz); return self.mapz.count(); }
pub fn keepSetz(self: *Regi, iozz: std.Io, jobz_iden: []const u8, keep: bool) bool { self.mute.lock(iozz) catch return false; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return false; entr.keep = keep; return true; }
pub fn keepNotzKill(self: *Regi, iozz: std.Io, jobz_iden: []const u8) void { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return; if (entr.keep or entr.done) return; entrKill(entr); }
pub fn stdiAcqu(self: *Regi, iozz: std.Io, jobz_iden: []const u8) ?std.Io.File { self.mute.lock(iozz) catch return null; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return null; if (entr.done or entr.stdi_clos_done) return null; const file = entr.chil.stdin orelse return null; entr.stdi_user += 1; return file; }
pub fn stdiRele(self: *Regi, iozz: std.Io, jobz_iden: []const u8, clos: bool) void { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return; entr.stdi_user -|= 1; if (clos) entr.stdi_clos_requ = true; if (entr.stdi_clos_requ and entr.stdi_user == 0) stdiLockClos(iozz, entr); }
pub fn stdiReti(self: *Regi, iozz: std.Io, jobz_iden: []const u8) void { while (true) { self.mute.lock(iozz) catch return; const entr = self.mapz.getPtr(jobz_iden) orelse { self.mute.unlock(iozz); return; }; if (entr.stdi_user == 0) { stdiLockClos(iozz, entr); self.mute.unlock(iozz); return; } self.mute.unlock(iozz); std.Io.sleep(iozz, .fromMilliseconds(CF.slee), .awake) catch return; } }
pub fn pausSetz(self: *Regi, iozz: std.Io, jobz_iden: []const u8, onzz: bool, nowz: i64) PausCode { self.mute.lock(iozz) catch return .fail; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return .none; if (entr.done) return .done; if (entr.paus == onzz) return .same; if (!pausctrl.treeFrez(iozz, entr.jobz, entr.chil.id, onzz)) return .fail; entr.paus = onzz; if (onzz) { entr.paus_star = nowz; } else { entr.paus_tota += nowz - entr.paus_star; } return .okzz; }
pub fn pausTota(self: *Regi, iozz: std.Io, jobz_iden: []const u8, nowz: i64) i64 { self.mute.lock(iozz) catch return 0; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return 0; return entr.paus_tota + (if (entr.paus) nowz - entr.paus_star else 0); }
pub fn allzUnloKill(self: *Regi) void { var iter = self.mapz.iterator(); while (iter.next()) |entr| { if (!entr.value_ptr.done) entrKill(entr.value_ptr); } }
pub fn idenKill(self: *Regi, iozz: std.Io, jobz_iden: []const u8) bool { self.mute.lock(iozz) catch return false; defer self.mute.unlock(iozz); const entr = self.mapz.getPtr(jobz_iden) orelse return false; if (entr.done) return true; entrKill(entr); return true; }
};
fn stdiLockClos(iozz: std.Io, entr: *Entr) void { if (entr.stdi_clos_done) return; if (entr.chil.stdin) |file| file.close(iozz); entr.chil.stdin = null; entr.stdi_clos_done = true; }
pub fn entrKill(entr: *Entr) void { if (builtin.os.tag == .windows) { if (entr.jobz) |hand| { _ = TerminateJobObject(hand, CF.exit); return; } if (entr.chil.id) |hand| _ = TerminateProcess(hand, CF.exit); } else { if (entr.chil.id) |pidz| { if (pidz > 0) { std.posix.kill(-pidz, std.posix.SIG.TERM) catch {}; std.posix.kill(-pidz, std.posix.SIG.KILL) catch {}; } } } }
pub fn winzJobzCrea(proc_hand: winz.HANDLE) ?winz.HANDLE { if (builtin.os.tag != .windows) return null; const jobz = CreateJobObjectW(null, null) orelse return null; _ = killOnzzClosSetz(jobz, true); if (AssignProcessToJobObject(jobz, proc_hand) == 0) { jobzRele(jobz); return null; } return jobz; }
